/* Calendars and the sky (src/js/2z-sky-core.js, 6zub-sky.js, 2z-data-astrology.js): the day converter, the astronomy under it, the zodiacs and precession, and the astrology pages.
   Table-driven: every row of ANCHORS is a date or an instant that a source gives, with where it comes from, and the code must reproduce it. The sources were opened for this project:
   · Meeus, Astronomical Algorithms (2nd ed., 1998), the worked examples of chapters 7 (Julian Day), 27 (seasons) and 49 (new Moon);
   · the Hong Kong Observatory's Gregorian–Lunar Calendar Conversion Table (hko.gov.hk, one text file a year; seven years read: 1901, 1928, 1950, 1984, 2012, 2033, 2057);
   · English Wikipedia: Equinox (the table of UT times of equinoxes and solstices, 2016 to 2030), Solar Hijri calendar (Nowruz 2016 to 2031, and its statement of the noon rule), Baháʼí Naw-Rúz (2024 to 2031),
     Rosh Hashanah (the infobox, 2025 to 2028);
   · the app's own tests/calendar.test.js (Hebrew holidays, Easter, tabular Islamic dates within a day of the sighted dates);
   · for the zodiacs: the third-party values of the Lahiri and Fagan-Bradley ayanamsa for 8 April 2024 (24.1961 and 25.0793 degrees), and EarthSky's published dates of the Sun's entry into Ophiuchus.
   Run: node tests/sky.test.js */
const fs = require('fs'); const path = require('path');
const SRC = path.join(__dirname, '..', 'src', 'js'); const C = require(path.join(SRC, '2z-sky-core.js'));
let pass = 0; let fail = 0; const ok = (n, c, x) => { if (c) pass++; else { fail++; console.log('FAIL', n, x === undefined ? '' : (typeof x === 'string' ? x : JSON.stringify(x)).slice(0, 400)); } };
const iso = (rd) => { const g = C.skyGregFromFixed(Math.floor(rd)); return `${g.y}-${String(g.m).padStart(2, '0')}-${String(g.d).padStart(2, '0')}`; };
const day = (y, m, d) => C.skyGregFixed(y, m, d); const jday = (y, m, d) => C.skyJulFixed(y, m, d);
const hm = (rd) => { const f = (rd - Math.floor(rd)) * 24; return Math.floor(f) * 60 + (f - Math.floor(f)) * 60; };         /* minutes after 0 h UT */
let anchors = 0; const anchor = (name, got, want, src) => { anchors++; ok(`${name} (${src})`, got === want, [got, want]); };

/* ═══ 1. day numbers: the Julian Day, the Gregorian and Julian calendars ═══ */
const JD = (rd) => C.skyJD(rd);
anchor('J2000: 1 January 2000 at 0 h is Julian Day 2451544.5', JD(day(2000, 1, 1)), 2451544.5, 'Meeus ch. 7');
anchor('Sputnik, 1957 October 4.81 is Julian Day 2436116.31 (so 0 h is .5)', JD(day(1957, 10, 4)), 2436115.5, 'Meeus ex. 7.a');
anchor('333 January 27.5 (Julian) is Julian Day 1842713.0', JD(jday(333, 1, 27)), 1842712.5, 'Meeus ex. 7.b');
anchor('837 April 10.3 (Julian) is Julian Day 2026871.8', JD(jday(837, 4, 10)), 2026871.5, 'Meeus ch. 7');
anchor('-1000 July 12.5 (Julian) is Julian Day 1356001.0', JD(jday(-1000, 7, 12)), 1356000.5, 'Meeus ch. 7');
anchor('-4712 January 1.5 (Julian) is Julian Day 0.0', JD(jday(-4712, 1, 1)), -0.5, 'Meeus ch. 7');
anchor('1900 January 1 at 0 h is Julian Day 2415020.5 (the epoch J1900.0 is January 0.5)', JD(day(1900, 1, 1)), 2415020.5, 'Meeus ch. 7');
anchor('Julian 4 October 1582 is followed by Gregorian 15 October 1582', jday(1582, 10, 4) + 1, day(1582, 10, 15), 'Meeus ch. 7; the reform of Gregory XIII');
anchor('1582 October 15 (Gregorian) is Julian Day 2299160.5', JD(day(1582, 10, 15)), 2299160.5, 'Meeus ch. 7');
anchor('1 January 2000 was a Saturday', C.skyWeekday(day(2000, 1, 1)), 6, 'the calendar');
anchor('Orthodox Christmas, 25 December (Julian) 2023, is 7 January 2024 (Gregorian)', iso(jday(2023, 12, 25)), '2024-01-07', 'the 13 days between the calendars in 1900 to 2099');
anchor('Julian 29 February 1900, a day the Gregorian calendar does not have, is 13 March 1900 (Gregorian)', iso(jday(1900, 2, 29)), '1900-03-13', 'the calendars');
{ let rt = 0; for (let rd = -1500000; rd < 3200000; rd += 991) { const g = C.skyGregFromFixed(rd); if (C.skyGregFixed(g.y, g.m, g.d) !== rd) rt++; const j = C.skyJulFromFixed(rd); if (C.skyJulFixed(j.y, j.m, j.d) !== rd) rt++; if (g.m < 1 || g.m > 12 || g.d < 1 || g.d > 31) rt++; }
  ok('Gregorian and Julian dates convert to day numbers and back, across 4,700 years', rt === 0, rt); }
ok('leap years: 1900 is not a Gregorian leap year but is a Julian one; 2000 is both; 1 BCE (year 0) is a leap year in both', !C.skyGregLeap(1900) && C.skyJulLeap(1900) && C.skyGregLeap(2000) && C.skyJulLeap(2000) && C.skyGregLeap(0) && C.skyJulLeap(0) && !C.skyGregLeap(-100) && C.skyGregLeap(-400));

